import{J as e,n as t,ot as n,q as r}from"./chunks/framework.1lTNTJZP.js";var i=JSON.parse(`{"title":"Class: ClientSocket","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: ClientSocket"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/raknet/classes/ClientSocket"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/raknet/classes/ClientSocket"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/raknet/src"}},"headers":[],"relativePath":"api/@jsprismarine/raknet/classes/ClientSocket.md","filePath":"api/@jsprismarine/raknet/classes/ClientSocket.md","lastUpdated":1794310385000}`),a={name:`api/@jsprismarine/raknet/classes/ClientSocket.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/raknet</a> / ClientSocket</p><h1 id="class-clientsocket" tabindex="-1">Class: ClientSocket <a class="header-anchor" href="#class-clientsocket" aria-label="Permalink to “Class: ClientSocket”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L115" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:115</a></p><p>RakNet from the other side: opens one outgoing connection and drives a <a href="./RakNetSession.html">RakNetSession</a> over it.</p><p>The reliability layer is not reimplemented here. A session does not know or care which kind of peer owns its socket - see <a href="./../#raknetpeer">RakNetPeer</a> - so ACK/NACK, ordering, fragmentation and retransmission are the exact code paths the server runs, which is the only way an outgoing connection is worth anything as a test of the incoming one.</p><p>What <em>is</em> here is the part that has no session to lean on: the offline exchange. None of it is reliable, so this class owns the retry timer and the MTU ladder, and hands over the moment <code>OpenConnectionReply2</code> arrives.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> client </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;"> new</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> ClientSocket</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(logger);</span></span>
<span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> session </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;"> await</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> client.connect</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">&#39;127.0.0.1&#39;</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">, </span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">19132</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">);</span></span>
<span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">client.on</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">&#39;encapsulated&#39;</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">, (frame) </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=&gt;</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> handle</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(frame.content));</span></span></code></pre></div><h2 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to “Extends”">​</a></h2><ul><li><code>EventEmitter</code></li></ul><h2 id="implements" tabindex="-1">Implements <a class="header-anchor" href="#implements" aria-label="Permalink to “Implements”">​</a></h2><ul><li><a href="./../#raknetpeer"><code>RakNetPeer</code></a></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new ClientSocket</strong>(<code>logger</code>, <code>options?</code>): <code>ClientSocket</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L130" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:130</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="logger" tabindex="-1">logger <a class="header-anchor" href="#logger" aria-label="Permalink to “logger”">​</a></h5><p><a href="./../#logger"><code>Logger</code></a></p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./../#clientsocketoptions"><code>ClientSocketOptions</code></a> = <code>{}</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>ClientSocket</code></p><h4 id="overrides" tabindex="-1">Overrides <a class="header-anchor" href="#overrides" aria-label="Permalink to “Overrides”">​</a></h4><p><code>EventEmitter.constructor</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="connect" tabindex="-1">connect() <a class="header-anchor" href="#connect" aria-label="Permalink to “connect()”">​</a></h3><blockquote><p><strong>connect</strong>(<code>address</code>, <code>port</code>): <code>Promise</code>&lt;<a href="./RakNetSession.html"><code>RakNetSession</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L155" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:155</a></p><p>Opens a connection and resolves once the handshake has completed.</p><p>Rejects with the server&#39;s own reason when it refuses us - full, banned, wrong protocol version - rather than letting all four failures look like a timeout.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="address" tabindex="-1">address <a class="header-anchor" href="#address" aria-label="Permalink to “address”">​</a></h5><p><code>string</code></p><p>the server&#39;s address.</p><h5 id="port" tabindex="-1">port <a class="header-anchor" href="#port" aria-label="Permalink to “port”">​</a></h5><p><code>number</code></p><p>the server&#39;s port.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./RakNetSession.html"><code>RakNetSession</code></a>&gt;</p><p>the connected session.</p><hr><h3 id="disconnect" tabindex="-1">disconnect() <a class="header-anchor" href="#disconnect" aria-label="Permalink to “disconnect()”">​</a></h3><blockquote><p><strong>disconnect</strong>(<code>reason?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L252" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:252</a></p><p>Says goodbye properly, so the server drops the session rather than timing it out.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="reason" tabindex="-1">reason? <a class="header-anchor" href="#reason" aria-label="Permalink to “reason?”">​</a></h5><p><code>string</code> = <code>&#39;client disconnect&#39;</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="getaddress" tabindex="-1">getAddress() <a class="header-anchor" href="#getaddress" aria-label="Permalink to “getAddress()”">​</a></h3><blockquote><p><strong>getAddress</strong>(): <a href="./InetAddress.html"><code>InetAddress</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L246" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:246</a></p><p>The local address the socket bound to, available once <a href="#connect">connect</a> has begun.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./InetAddress.html"><code>InetAddress</code></a></p><hr><h3 id="getclientguid" tabindex="-1">getClientGuid() <a class="header-anchor" href="#getclientguid" aria-label="Permalink to “getClientGuid()”">​</a></h3><blockquote><p><strong>getClientGuid</strong>(): <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L237" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:237</a></p><p>Our own guid - the one the server knows us by.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>bigint</code></p><hr><h3 id="getlogger" tabindex="-1">getLogger() <a class="header-anchor" href="#getlogger" aria-label="Permalink to “getLogger()”">​</a></h3><blockquote><p><strong>getLogger</strong>(): <a href="./../#logger"><code>Logger</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L241" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:241</a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#logger"><code>Logger</code></a></p><h4 id="implementation-of" tabindex="-1">Implementation of <a class="header-anchor" href="#implementation-of" aria-label="Permalink to “Implementation of”">​</a></h4><p><a href="./../#raknetpeer"><code>RakNetPeer</code></a>.<a href="./../#getlogger-2"><code>getLogger</code></a></p><hr><h3 id="getsession" tabindex="-1">getSession() <a class="header-anchor" href="#getsession" aria-label="Permalink to “getSession()”">​</a></h3><blockquote><p><strong>getSession</strong>(): <a href="./RakNetSession.html"><code>RakNetSession</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L232" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:232</a></p><p>The live session, or null before the handshake completes and after it ends.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./RakNetSession.html"><code>RakNetSession</code></a> | <code>null</code></p><hr><h3 id="kill" tabindex="-1">kill() <a class="header-anchor" href="#kill" aria-label="Permalink to “kill()”">​</a></h3><blockquote><p><strong>kill</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L257" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:257</a></p><p>Tears everything down. The socket cannot be reused afterwards.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="onofflinefailure" tabindex="-1">onOfflineFailure() <a class="header-anchor" href="#onofflinefailure" aria-label="Permalink to “onOfflineFailure()”">​</a></h3><blockquote><p><strong>onOfflineFailure</strong>(<code>reason</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L366" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:366</a></p><p>The server refused us, and said why. Terminal: retrying cannot change the answer.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="reason-1" tabindex="-1">reason <a class="header-anchor" href="#reason-1" aria-label="Permalink to “reason”">​</a></h5><p><code>string</code></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="onopenconnectionreply1" tabindex="-1">onOpenConnectionReply1() <a class="header-anchor" href="#onopenconnectionreply1" aria-label="Permalink to “onOpenConnectionReply1()”">​</a></h3><blockquote><p><strong>onOpenConnectionReply1</strong>(<code>reply</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L325" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:325</a></p><p>The server is willing and has told us the MTU it saw. Everything downstream sizes buffers against this, so it is clamped exactly as the server clamps ours.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="reply" tabindex="-1">reply <a class="header-anchor" href="#reply" aria-label="Permalink to “reply”">​</a></h5><p><a href="./OpenConnectionReply1.html"><code>OpenConnectionReply1</code></a></p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="onopenconnectionreply2" tabindex="-1">onOpenConnectionReply2() <a class="header-anchor" href="#onopenconnectionreply2" aria-label="Permalink to “onOpenConnectionReply2()”">​</a></h3><blockquote><p><strong>onOpenConnectionReply2</strong>(<code>reply</code>, <code>rinfo</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L337" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:337</a></p><p>The connection is accepted: build the session and open the connected handshake.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="reply-1" tabindex="-1">reply <a class="header-anchor" href="#reply-1" aria-label="Permalink to “reply”">​</a></h5><p><a href="./OpenConnectionReply2.html"><code>OpenConnectionReply2</code></a></p><h5 id="rinfo" tabindex="-1">rinfo <a class="header-anchor" href="#rinfo" aria-label="Permalink to “rinfo”">​</a></h5><p><code>RemoteInfo</code></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="onunconnectedpong" tabindex="-1">onUnconnectedPong() <a class="header-anchor" href="#onunconnectedpong" aria-label="Permalink to “onUnconnectedPong()”">​</a></h3><blockquote><p><strong>onUnconnectedPong</strong>(<code>pong</code>, <code>rinfo</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L352" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:352</a></p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="pong" tabindex="-1">pong <a class="header-anchor" href="#pong" aria-label="Permalink to “pong”">​</a></h5><p><a href="./UnconnectedPong.html"><code>UnconnectedPong</code></a></p><h5 id="rinfo-1" tabindex="-1">rinfo <a class="header-anchor" href="#rinfo-1" aria-label="Permalink to “rinfo”">​</a></h5><p><code>RemoteInfo</code></p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="ping" tabindex="-1">ping() <a class="header-anchor" href="#ping" aria-label="Permalink to “ping()”">​</a></h3><blockquote><p><strong>ping</strong>(<code>address</code>, <code>port</code>, <code>timeoutMs?</code>): <code>Promise</code>&lt;<a href="./../#pingresult"><code>PingResult</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L195" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:195</a></p><p>Asks a server for its MOTD without connecting. Several may be in flight at once, so a server list can be refreshed in one pass.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="address-1" tabindex="-1">address <a class="header-anchor" href="#address-1" aria-label="Permalink to “address”">​</a></h5><p><code>string</code></p><p>the server&#39;s address.</p><h5 id="port-1" tabindex="-1">port <a class="header-anchor" href="#port-1" aria-label="Permalink to “port”">​</a></h5><p><code>number</code></p><p>the server&#39;s port.</p><h5 id="timeoutms" tabindex="-1">timeoutMs? <a class="header-anchor" href="#timeoutms" aria-label="Permalink to “timeoutMs?”">​</a></h5><p><code>number</code> = <code>2_000</code></p><p>how long to wait for the pong.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../#pingresult"><code>PingResult</code></a>&gt;</p><hr><h3 id="removesession" tabindex="-1">removeSession() <a class="header-anchor" href="#removesession" aria-label="Permalink to “removeSession()”">​</a></h3><blockquote><p><strong>removeSession</strong>(<code>session</code>, <code>reason?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L307" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:307</a></p><p>The session has finished disconnecting and should be forgotten. Called exactly once per session, from <a href="./RakNetSession.html#disconnect">Session.disconnect</a>.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="session" tabindex="-1">session <a class="header-anchor" href="#session" aria-label="Permalink to “session”">​</a></h5><p><a href="./RakNetSession.html"><code>RakNetSession</code></a></p><h5 id="reason-2" tabindex="-1">reason? <a class="header-anchor" href="#reason-2" aria-label="Permalink to “reason?”">​</a></h5><p><code>string</code></p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="implementation-of-1" tabindex="-1">Implementation of <a class="header-anchor" href="#implementation-of-1" aria-label="Permalink to “Implementation of”">​</a></h4><p><a href="./../#raknetpeer"><code>RakNetPeer</code></a>.<a href="./../#removesession-2"><code>removeSession</code></a></p><hr><h3 id="sendbuffer" tabindex="-1">sendBuffer() <a class="header-anchor" href="#sendbuffer" aria-label="Permalink to “sendBuffer()”">​</a></h3><blockquote><p><strong>sendBuffer</strong>(<code>buffer</code>, <code>rinfo</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L299" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:299</a></p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="buffer" tabindex="-1">buffer <a class="header-anchor" href="#buffer" aria-label="Permalink to “buffer”">​</a></h5><p><code>Buffer</code></p><h5 id="rinfo-2" tabindex="-1">rinfo <a class="header-anchor" href="#rinfo-2" aria-label="Permalink to “rinfo”">​</a></h5><p><code>RemoteInfo</code></p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="sendpacket" tabindex="-1">sendPacket() <a class="header-anchor" href="#sendpacket" aria-label="Permalink to “sendPacket()”">​</a></h3><blockquote><p><strong>sendPacket</strong>(<code>packet</code>, <code>rinfo</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/356f0fb025e5b807e6a5a83c697e6f4fc80a31c6/packages/raknet/src/ClientSocket.ts#L294" target="_blank" rel="noreferrer">raknet/src/ClientSocket.ts:294</a></p><p>Encodes and sends a packet to <code>rinfo</code>. Sessions never touch a socket directly - a closed or unbound one has to be the peer&#39;s problem, since only the peer knows.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packet" tabindex="-1">packet <a class="header-anchor" href="#packet" aria-label="Permalink to “packet”">​</a></h5><p><a href="./Packet.html"><code>Packet</code></a></p><h5 id="rinfo-3" tabindex="-1">rinfo <a class="header-anchor" href="#rinfo-3" aria-label="Permalink to “rinfo”">​</a></h5><p><code>RemoteInfo</code></p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="implementation-of-2" tabindex="-1">Implementation of <a class="header-anchor" href="#implementation-of-2" aria-label="Permalink to “Implementation of”">​</a></h4><p><a href="./../#raknetpeer"><code>RakNetPeer</code></a>.<a href="./../#sendpacket-2"><code>sendPacket</code></a></p>`,186)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};